package com.example.editor.integration.adapter.besser;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import com.example.editor.definition.EditorDefinitionModel;
import com.example.editor.definition.EditorDefinitionTestFixtures;
import com.example.editor.definition.RepresentationDefinition;
import com.example.editor.definition.RepresentationKind;
import com.example.editor.integration.IntegrationArtifactKind;
import com.example.editor.integration.IntegrationProfileModel;
import com.example.editor.integration.IntegrationTarget;
import com.example.editor.integration.compiler.TechnologyAdapterTestFixtures;
import com.example.editor.integration.compiler.TechnologyCompilationRequest;
import com.example.editor.integration.projection.CanonicalArtifactContent;

class BesserWebModelingEditorTechnologyAdapterTests {
    private final BesserWebModelingEditorTechnologyAdapter adapter=new BesserWebModelingEditorTechnologyAdapter(TechnologyAdapterTestFixtures.MAPPER);
    @Test void targetsBesserWebModelingEditor(){assertThat(adapter.technology().name()).isEqualTo("BESSER_WEB_MODELING_EDITOR");}
    @Test void generatesNpmExtensionPackage(){var paths=paths(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()));assertThat(paths).anyMatch(value->value.endsWith("package.json")).anyMatch(value->value.endsWith("src/index.ts")).anyMatch(value->value.endsWith("src/hydra-semantic-runtime.ts")).anyMatch(value->value.endsWith("src/hydra-runtime.ts")).anyMatch(value->value.endsWith("tests/extension.test.ts"));}
    @Test void declaresBesserWmePeerDependency(){assertThat(text(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()),"package.json")).contains("@besser/wme","peerDependencies");}
    @Test void generatesDiagramRegistrationAndPalette(){var result=adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest());assertThat(text(result,"hydra-diagram-type.ts")).contains("HYDRA_META_MODEL_2_1","Person");assertThat(text(result,"hydra-palette.ts")).contains("Person","Employer","Display");}
    @Test void generatesCanonicalModelCodec(){assertThat(text(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()),"hydra-model-codec.ts")).contains("HydraCanonicalModel","people","encodeHydraModel");}
    @Test void generatesValidationQuickFixEventAndGamificationBridges(){var paths=paths(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()));assertThat(paths).anyMatch(value->value.endsWith("hydra-validation.ts")).anyMatch(value->value.endsWith("hydra-quickfix.ts")).anyMatch(value->value.endsWith("hydra-events.ts")).anyMatch(value->value.endsWith("hydra-gamification.ts"));}
    @Test void executesTransactionalRuntimeInsteadOfPassiveCapabilityInterfaces(){var result=adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest());assertThat(text(result,"hydra-runtime.ts")).contains("class HydraBesserWmeRuntime","new HydraSemanticRuntime(engine)","BESSER_WME_DRAFT_VALIDATE","BESSER_WME_COMMIT","this.lifecycle.restore(before)");assertThat(text(result,"hydra-validation.ts")).contains("class HydraValidationService","this.runtime.validate");assertThat(text(result,"hydra-events.ts")).contains("class HydraWmeEventService","publishAfterCommit","this.runtime.commit");assertThat(text(result,"hydra-gamification.ts")).contains("class HydraGamificationService","this.runtime.gamification");assertThat(text(result,"index.ts")).contains("hydra-runtime.js","hydra-semantic-runtime.js");}
    @Test void generatedVitestSuiteProtectsTransactionalLifecycle(){String tests=text(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()),"tests/extension.test.ts");assertThat(tests).contains("keeps draft validation side-effect free and commits only confirmed states","rolls back the complete runtime checkpoint when a commit capability fails","does not replay changes made while HYDRA is disabled","runtime.checkpoint()).toEqual(before)","hydraRuntimeActivation.setEnabled(false)");}
    @Test void generatesBackendConversionBoundary(){assertThat(text(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()),"hydra-backend-client.ts")).contains("besser_api","fetch","hydra/convert");}
    @Test void embedsCanonicalDocuments(){var paths=paths(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()));assertThat(paths).anyMatch(value->value.endsWith("resources/hydra/metamodel.json")).anyMatch(value->value.endsWith("resources/hydra/editor_definition.json"));}
    @Test void verifiesWithNpmCheck(){assertThat(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()).verificationSteps()).hasSize(2).satisfiesExactly(
            install -> assertThat(install.command()).containsExactly("npm","install","--ignore-scripts"),
            check -> assertThat(check.command()).containsExactly("npm","run","check"));}
    @Test void generationIsDeterministic(){assertThat(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()).files()).usingRecursiveComparison().isEqualTo(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()).files());}
    @Test void honorsPackageAndDiagramType(){var result=adapter.compile(configured(Map.of("packageName","@example/people-wme","diagramType","people.custom")));assertThat(result.metadata()).containsEntry("packageName","@example/people-wme").containsEntry("diagramType","people.custom");assertThat(text(result,"hydra-diagram-type.ts")).contains("people.custom");}
    @Test void rejectsMissingEditorDefinition(){var source=TechnologyAdapterTestFixtures.besserWebRequest();var artifacts=source.artifacts().stream().filter(value->value.kind()!=IntegrationArtifactKind.EDITOR_DEFINITION).toList();assertThatThrownBy(()->adapter.compile(new TechnologyCompilationRequest(source.profile(),artifacts,"test",Map.of()))).hasMessageContaining("EDITOR_DEFINITION");}
    @Test void warnsForNonDiagramRepresentations(){var source=TechnologyAdapterTestFixtures.besserWebRequest();var editor=EditorDefinitionTestFixtures.editor();var table=new RepresentationDefinition("representation:table","Table",RepresentationKind.TABLE,List.of(),List.of(),List.of(),List.of(),true,Map.of());var changed=new EditorDefinitionModel(editor.schemaVersion(),editor.id(),editor.metamodelId(),editor.name(),List.of(editor.representations().getFirst(),table),editor.palette(),editor.forms(),editor.capabilityManifest(),editor.runtimePolicy(),editor.annotations());var artifacts=new ArrayList<>(source.artifacts());artifacts.removeIf(value->value.kind()==IntegrationArtifactKind.EDITOR_DEFINITION);artifacts.add(new CanonicalArtifactContent(IntegrationArtifactKind.EDITOR_DEFINITION,changed.id(),"application/json",TechnologyAdapterTestFixtures.MAPPER.writeValueAsBytes(changed)));assertThat(adapter.compile(new TechnologyCompilationRequest(source.profile(),artifacts,"test",Map.of())).diagnostics()).extracting(value->value.code()).contains("BESSER_WME_NON_DIAGRAM_VIEWPOINT");}
    @Test void documentsTechnologyProjectionAndCanonicalSource(){assertThat(text(adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest()),"README.md")).contains("MetaModel 2.1","@besser/wme","technology projections","HYDRA stays the semantic source of truth");}
    @Test void consumesFullTextualStackIncludingCustomizationAndNeutralLayers(){var result=adapter.compile(TechnologyAdapterTestFixtures.besserWebFullTextualRequest());var paths=paths(result);assertThat(paths).anyMatch(v->v.endsWith("hydra-textual-full-stack.ts")).anyMatch(v->v.endsWith("hydra/textual-editor-customization.json")).anyMatch(v->v.endsWith("hydra/textual-full-stack.json"));assertThat(text(result,"hydra-textual-full-stack.ts")).contains("hydraTextualCustomization","validation:true","quickFixes:true","events:true","eventFlows:true","gamification:true","afterCommit");assertThat(text(result,"index.ts")).contains("hydra-textual-full-stack.js");}
    @Test void plainWmePackageDoesNotReferenceMissingTextualModule(){var result=adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest());assertThat(text(result,"index.ts")).doesNotContain("hydra-textual-full-stack.js");}
    private TechnologyCompilationRequest configured(Map<String,String> settings){var source=TechnologyAdapterTestFixtures.besserWebRequest();var t=source.profile().target();var target=new IntegrationTarget(t.technology(),t.kind(),t.technologyVersion(),t.projectId(),t.moduleName(),t.buildSystem(),t.sourceRoots(),t.configurationFiles(),t.endpoint(),settings);var p=source.profile();var profile=new IntegrationProfileModel(p.schemaVersion(),p.id(),p.metamodelId(),p.name(),target,p.deliveryMode(),p.features(),p.artifacts(),p.mappings(),p.injectionPolicy(),p.requiredCapabilities(),p.annotations());return new TechnologyCompilationRequest(profile,source.artifacts(),"test",Map.of());}
    private List<String> paths(com.example.editor.integration.compiler.TechnologyCompilationResult result){return result.files().stream().map(value->value.relativePath()).toList();}
    @Test void executesNeutralVisualCustomizationInGeneratedWmeExtension(){var result=adapter.compile(TechnologyAdapterTestFixtures.besserWebRequest());assertThat(paths(result)).anyMatch(v->v.endsWith("src/hydra-visual-full-stack.ts")).anyMatch(v->v.endsWith("resources/hydra/visual-editor-definition.json")).anyMatch(v->v.endsWith("resources/hydra/visual-full-stack.json"));assertThat(text(result,"index.ts")).contains("hydra-visual-full-stack.js");assertThat(text(result,"extension.test.ts")).contains("executes HYDRA visual customization inside the WME host bridge","resolveNodeAppearance","#fc0","ELLIPSE");assertThat(text(result,"hydra-visual-full-stack.ts")).contains("applyNodeAppearance","applyEdgeAppearance","applyModel","fallbackUsed");}

    private String text(com.example.editor.integration.compiler.TechnologyCompilationResult result,String suffix){return result.files().stream().filter(value->value.relativePath().endsWith(suffix)).map(value->new String(value.content(),StandardCharsets.UTF_8)).findFirst().orElseThrow();}
}
